import { Box, Stack } from '@mui/material';
import {useTheme} from '@mui/material/styles';
import React from 'react';
import { Chat_History } from '../../data';
import { DocMsg, LinkMsg, MediaMsg, ReplyMsg, TextMessage, Timeline } from './MessageType'; 

const Message = ({menu}) => {
    const theme = useTheme();
    return (
        <Box p={3} sx={{backgroundColor: theme.palette.mode==="light"?"#f5f5f5":theme.palette.background.paper}}>
            <Stack spacing={3}>
                {
                    Chat_History.map((el) => {
                        switch (el.type) {
                            case "divider": {
                                return <Timeline el={el}/>
                            }
                            case "msg": {
                                switch (el.subtype) {
                                    case "img": {
                                        return <MediaMsg el={el} menu={menu}/>
                                    }
                                    case "doc": {
                                        return <DocMsg el={el} menu={menu}/>
                                    }
                                    case "link": {
                                        return <LinkMsg el={el} menu={menu}/>
                                    }
                                    case "reply": {
                                        return <ReplyMsg el={el} menu={menu}/>
                                    }
                                    default: {
                                        return <TextMessage el={el} menu={menu}/>
                                    }
                                }
                            }
                            default:{
                                return <></>;
                            }
                        }
                    })
                }
            </Stack>

        </Box>
    )
}

export default Message;