import { Stack, Box } from "@mui/material";
import React, { useEffect, useRef } from "react";
import { useTheme } from "@mui/material/styles";
import { SimpleBarStyle } from "../../components/Scrollbar";

import { ChatHeader, ChatFooter } from "../../components/Chat";
import useResponsive from "../../hooks/useResponsive";
import { Chat_History } from "../../data";
import { DocMsg, LinkMsg, MediaMsg, ReplyMsg, TextMsg, Timeline, } from "../../sections/main/Conversation";
import { useDispatch, useSelector } from "react-redux";
import { FetchCurrentMessages, SetCurrentConversation, } from "../../redux/slices/conversation";
import Message from "../../components/Conversation/Message";
import webSocketService from "../../webSocketService";

const Conversation = ({ isMobile, menu }) => {
  const dispatch = useDispatch();
  const user_id = window.localStorage.getItem("user_id");

  const { conversations, current_messages } = useSelector(
    (state) => state.conversation.direct_chat
  );
  const { room_id } = useSelector((state) => state.app);

  useEffect(() => {
    const subscriptionsMap = new Map(); // Track active subscriptions
    const subscriptions = [];
    const subscribeToEndpoint = (endpoint, callback) => {
      // Check if already subscribed
      if (!subscriptionsMap.has(endpoint)) {
        const subscription = webSocketService.subscribe(endpoint, callback);
        subscriptionsMap.set(endpoint, subscription); // Store subscription
        subscriptions.push(subscription); // Keep the existing array of subscriptions
      }
    };

    const current = conversations.find((el) => el?.id === room_id);

    subscribeToEndpoint(`/user/${user_id}/topic/get_messages`, (data) => {
      const parsedResponse = JSON.parse(data);
      dispatch(FetchCurrentMessages({ messages: parsedResponse }));
    });
    webSocketService.sendMessage("/app/get_messages", JSON.stringify({ conversation_id: current?.id }));
    dispatch(SetCurrentConversation({ room_id: current?.id }));

    return () => {
      subscriptions.forEach((el) => {
        el?.unsubscribe();
      });
      subscriptionsMap.clear();
    };

  }, [room_id]);

  return (
    <Box p={isMobile ? 1 : 3}>
      <Stack spacing={3}>
        {current_messages.map((el, idx) => {
          switch (el?.type) {
            case "divider":
              return (
                // Timeline
                <Timeline el={el} />
              );

            case "msg":
              switch (el.subtype) {
                case "MEDIA":
                  return (
                    // Media Message
                    <MediaMsg el={el} menu={menu} />
                  );

                case "DOCUMENT":
                  return (
                    // Doc Message
                    <DocMsg el={el} menu={menu} />
                  );
                case "LINK":
                  return (
                    //  Link Message
                    <LinkMsg el={el} menu={menu} />
                  );

                case "REPLY":
                  return (
                    //  ReplyMessage
                    <ReplyMsg el={el} menu={menu} />
                  );

                default:
                  return (
                    // Text Message
                    <TextMsg el={el} menu={menu} />
                  );
              }

            default:
              return <></>;
          }
        })}
      </Stack>
    </Box>
  );
};

const ChatComponent = () => {
  const isMobile = useResponsive("between", "md", "xs", "sm");
  const theme = useTheme();

  const messageListRef = useRef(null);

  const { current_messages } = useSelector(
    (state) => state.conversation.direct_chat
  );

  useEffect(() => {
    // Scroll to the bottom of the message list when new messages are added
    messageListRef.current.scrollTop = messageListRef.current.scrollHeight;
  }, [current_messages]);

  return (
    <Stack
      height={"100%"}
      maxHeight={"100vh"}
      width={isMobile ? "100vw" : "auto"}
    >
      {/*  */}
      <ChatHeader />
      <Box
        ref={messageListRef}
        width={"100%"}
        sx={{
          position: "relative",
          flexGrow: 1,
          overflowY: "scroll",

          backgroundColor:
            theme.palette.mode === "light"
              ? "#f5f5f5"
              : theme.palette.background,

          boxShadow: "0px 0px 2px rgba(0, 0, 0, 0.25)",
        }}
      >
        <Conversation menu={true} isMobile={isMobile} />
      </Box>

      {/*  */}
      <ChatFooter />
    </Stack>
  );
};

export default ChatComponent;

export { Conversation };