import { format, getTime, formatDistanceToNow } from 'date-fns';

// ----------------------------------------------------------------------

export function fDate(date) {
  return format(new Date(date), 'dd MMMM yyyy');
}

export function fDateTime(date) {
  return format(new Date(date), 'dd MMM yyyy HH:mm');
}

export function fTimestamp(date) {
  return getTime(new Date(date));
}

export function fDateTimeSuffix(date) {
  return format(new Date(date), 'hh:mm p');
}

export function fToNow(date) {
  return formatDistanceToNow(new Date(date), {
    addSuffix: true,
  });
}

export function convertToIST(utcDateString) {
  // Create a Date object from the UTC string
  const date = new Date(utcDateString);

  // Calculate the IST offset in milliseconds (IST is UTC + 5 hours 30 minutes)
  // const istOffset = 5.5 * 60 * 60 * 1000;

  // Convert the UTC time to IST by adding the offset
  const istDate = new Date(date.getTime());

  // Get the hours and minutes in IST
  const hours = String(istDate.getHours()).padStart(2, '0');
  const minutes = String(istDate.getMinutes()).padStart(2, '0');

  // Return the time in hh:mm format
  return `${hours}:${minutes}`;
}
